#if ATARASY_UI_TEST_FIXTURES
import Foundation
import SwiftUI
import AtarasyCore

// Recorded synthetic service responses. No network, provider, or real authenticator is used here.
private enum DigitalFixtureData {
    static let bytes = Data(base64Encoded: "")!
    static var value: [String: Any] { try! JSONSerialization.jsonObject(with: bytes) as! [String: Any] }
    static func data(_ key: String) -> Data { try! JSONSerialization.data(withJSONObject: value[key]!) }
}
private struct DigitalFixtureVault: MemberSessionVault {
    let info: MemberSessionInfo
    func load(environment: MemberEnvironment, household: String) throws -> StoredMemberSession? {
        let object: [String: Any] = ["token": "amr1_" + String(repeating: "A", count: 43), "info": try JSONSerialization.jsonObject(with: JSONEncoder().encode(info))]
        return try JSONDecoder().decode(StoredMemberSession.self, from: JSONSerialization.data(withJSONObject: object))
    }
    func save(_ session: StoredMemberSession, environment: MemberEnvironment) throws {}
    func remove(environment: MemberEnvironment, household: String) throws {}
}
private actor DigitalFixtureTransport: MemberHTTPTransport {
    var submitted = false
    func send(_ request: URLRequest) async throws -> MemberHTTPReply {
        let path = request.url!.path
        let bytes: Data
        if path == "/auth/session" { bytes = DigitalFixtureData.data("session") }
        else if path.hasSuffix("/submit") { submitted = true; throw URLError(.networkConnectionLost) }
        else if path.hasSuffix("/outcome") && submitted { bytes = DigitalFixtureData.data("committed") }
        else if path.hasSuffix("/cancel") { bytes = Data(#"{"cancelled":true}"#.utf8) }
        else { bytes = DigitalFixtureData.data("prepared") }
        return .init(url: request.url!, status: 200, contentType: "application/json", cacheControl: "no-store", data: bytes)
    }
}
@MainActor private final class DigitalFixturePasskeys: MemberPasskeyAuthorising {
    func authorise(_ ceremony: MemberCeremony, kind: NativePasskeyOptions.Kind) async throws -> MemberPasskeyResponse {
        guard kind == .decision, case .string(let challenge) = ceremony.publicKey["challenge"],
              case .array(let allowed) = ceremony.publicKey["allowCredentials"], case .object(let credential) = allowed[0], case .string(let id) = credential["id"] else { throw NativePasskeyFailure.invalidOptions }
        let data = try JSONSerialization.data(withJSONObject: ["type":"webauthn.get", "origin":"https://unit.example", "challenge":challenge])
        let encoded = data.base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
        return .assertion(id: id, clientDataJSON: encoded, authenticatorData: "YQ", signature: "YQ", userHandle: "YQ")
    }
}
@MainActor private final class DigitalFixtureModel: ObservableObject {
    let flow: MemberDigitalFlow
    let client: MemberClient
    let session: MemberSessionInfo
    let detail: MemberOfferDetail
    let draft: MemberDigitalDraft
    @Published var ready = false
    init() {
        session = try! JSONDecoder().decode(MemberSessionInfo.self, from: DigitalFixtureData.data("session"))
        let raw = DigitalFixtureData.value["detail"] as! [String: Any]
        detail = try! MemberOfferDetail.decode(DigitalFixtureData.data("detail"), expectedID: raw["id"] as! String, household: session.household)
        let view = (DigitalFixtureData.value["prepared"] as! [String: Any])["review"] as! [String: Any]
        let approval = try! MemberApproval.decode(JSONSerialization.data(withJSONObject: view["approval"]!), detail: detail)
        var choices = MemberDigitalDraft(approval: approval)
        for candidate in approval.candidates { try! choices.choose(.keep, candidate: candidate.id) }; draft = choices
        let environment = try! MemberEnvironment(name: "test", origin: URL(string: "https://unit.example")!)
        client = MemberClient(environment: environment, transport: DigitalFixtureTransport(), vault: DigitalFixtureVault(info: session), now: { 1_800_000_000_001 })
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("digital-ui-fixture")
        if ProcessInfo.processInfo.arguments.contains("--fresh") { try? FileManager.default.removeItem(at: directory) }
        flow = MemberDigitalFlow(environment: environment, service: client, passkeys: DigitalFixturePasskeys(), store: try! FileMemberOperationStore(directory: directory), now: { 1_800_000_000_001 })
    }
    func start() async { _ = try? await client.restore(household: session.household); flow.setSession(session); ready = true }
}
struct MemberDigitalFixtureView: View {
    @StateObject private var model = DigitalFixtureModel()
    var body: some View {
        MemberDigitalScreen(flow: model.flow, detail: model.detail, draft: model.draft)
            .disabled(!model.ready)
            .safeAreaInset(edge: .top) { Text("Synthetic digital fixture. No payment or actual passkey.").font(.caption) }
            .task { await model.start() }
    }
}
